SELECT

FROM book b
LEFT JOIN book_category c ON b.category_id = c.id
LEFT JOIN book_reading_progress p ON p.book_id = b.id AND p.user_uuid = #{userUuid}
LEFT JOIN book_chapter pc ON pc.id = p.chapter_id AND pc.status = 1
LEFT JOIN book_user_shelf s ON s.book_id = b.id AND s.user_uuid = #{userUuid}
LEFT JOIN book_user_review r ON r.book_id = b.id AND r.user_uuid = #{userUuid}


    AND s.status = #{shelfStatus}



        ORDER BY CASE WHEN p.update_time IS NULL THEN 1 ELSE 0 END, p.update_time DESC, b.id DESC


        ORDER BY b.title ASC, b.id ASC


        ORDER BY chapter_count DESC, b.id DESC


        ORDER BY word_total DESC, b.id DESC


        ORDER BY b.update_time DESC, b.id DESC


LIMIT #{limit} OFFSET #{offset}

SELECT
,
(SELECT COUNT(*) FROM book_chapter ch2
 WHERE ch2.book_id = b.id AND ch2.status = 1 AND ch2.sort_order < pc.sort_order) AS progress_chapter_index
FROM book b
LEFT JOIN book_category c ON b.category_id = c.id
JOIN book_reading_progress p ON p.book_id = b.id AND p.user_uuid = #{userUuid}
LEFT JOIN book_chapter pc ON pc.id = p.chapter_id AND pc.status = 1
LEFT JOIN book_user_shelf s ON s.book_id = b.id AND s.user_uuid = #{userUuid}
LEFT JOIN book_user_review r ON r.book_id = b.id AND r.user_uuid = #{userUuid}
WHERE b.status = 1
ORDER BY p.update_time DESC, b.id DESC
LIMIT #{limit}

SELECT

FROM book b
LEFT JOIN book_category c ON b.category_id = c.id
LEFT JOIN book_reading_progress p ON p.book_id = b.id AND p.user_uuid = #{userUuid}
LEFT JOIN book_chapter pc ON pc.id = p.chapter_id AND pc.status = 1
LEFT JOIN book_user_shelf s ON s.book_id = b.id AND s.user_uuid = #{userUuid}
LEFT JOIN book_user_review r ON r.book_id = b.id AND r.user_uuid = #{userUuid}
WHERE b.id = #{id} AND b.status = 1

